#!/usr/bin/env python3
"""embed_file.py — turn a data file into a C header that embeds it.

Usage:
    tools/embed_file.py <input> <output.h> <symbol>

The generated header declares

    static const unsigned char <symbol>[];
    static const size_t <symbol>_size;

so anything compiled with it can write the bytes out without carrying the
original file. The CA bundle is the first user: the device has no usable
system trust store, and the bundle has to reach the fake root before git can
clone over HTTPS.

The output depends only on the input bytes, which keeps it reproducible.
"""

import sys


def main() -> int:
    if len(sys.argv) != 4:
        sys.stderr.write(__doc__)
        return 2

    source, target, symbol = sys.argv[1], sys.argv[2], sys.argv[3]
    if not symbol.isidentifier():
        sys.stderr.write("embed_file.py: %r is not a C identifier\n" % symbol)
        return 2

    with open(source, "rb") as f:
        data = f.read()

    lines = [
        "// Generated by tools/embed_file.py from %s. Do not edit." % source,
        "#pragma once",
        "#include <stddef.h>",
        "",
        "static const unsigned char %s[] = {" % symbol,
    ]
    for offset in range(0, len(data), 16):
        chunk = data[offset:offset + 16]
        lines.append("    " + ", ".join("0x%02x" % b for b in chunk) + ",")
    lines += [
        "};",
        "",
        "static const size_t %s_size = sizeof %s;" % (symbol, symbol),
        "",
    ]

    with open(target, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
